mapper.select:
SELECT la.id, la.application_no, la.employee_id, e.name AS employee_name, la.leave_type_id, lt.leave_name AS leave_type_name, la.start_time, la.end_time, la.duration, la.unit, la.reason, la.process_instance_id, la.status, la.create_time, la.update_time FROM hr_leave_application la LEFT JOIN hr_employee e ON la.employee_id = e.id LEFT JOIN hr_leave_type lt ON la.leave_type_id = lt.id WHERE la.tenant_id = #{tenantId} AND la.deleted = 0
AND la.employee_id = #{query.employeeId}
AND la.leave_type_id = #{query.leaveTypeId}
AND la.status = #{query.status}
AND la.start_time >= #{query.startTimeFrom}
AND la.start_time <= #{query.startTimeTo}
ORDER BY la.create_time DESC
